const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.1/companies/%7Bcompany_id%7D/uploads',
  headers: {'content-type': 'application/json'},
  body: {
    response_filename: 'Contract.pdf',
    response_content_type: 'application/pdf',
    attachment_content_disposition: true,
    size: 1234567,
    segments: [
      {
        size: 5242880,
        sha256: '70c50ce1892d79bc900a0e753b12126273ea8e80051386531b3c10dc68d33926',
        md5: '85a13cb23a2fded1b6c6b78a48507a12',
        etag: '9c6243014e7ae154a58d29294906d4a960c60765'
      }
    ]
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.1/companies/%7Bcompany_id%7D/uploads"),
    Content = new StringContent("{\"response_filename\":\"Contract.pdf\",\"response_content_type\":\"application/pdf\",\"attachment_content_disposition\":true,\"size\":1234567,\"segments\":[{\"size\":5242880,\"sha256\":\"70c50ce1892d79bc900a0e753b12126273ea8e80051386531b3c10dc68d33926\",\"md5\":\"85a13cb23a2fded1b6c6b78a48507a12\",\"etag\":\"9c6243014e7ae154a58d29294906d4a960c60765\"}]}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

